data class City(
    val name: String,
    val latitude: Double,
    val longitude: Double,
    val zoneId: String,
    val climate: MonthlyClimate,
)

data class Country(
    val code: String,
    val name: String,
    val currency: String,
    /** Typical household electricity price incl. taxes, local currency per kWh (approx. 2025). */
    val tariff: Double,
    /** Grid emission intensity, g CO₂ per kWh (approx. 2024). */
    val co2: Double,
    /** Typical annual consumption of a flat / small household, kWh. */
    val householdKwh: Double,
    val season: LoadSeason,
    val inverterLimitW: Double,
    /** Short note on plug-in solar rules; null when the table has no reliable rule for the country. */
    val plugInNote: String?,
    /** Typical price of a 2-panel balcony kit, local currency (approx.). */
    val kitPrice: Double,
    val cities: List<City>,
) {
    val southern: Boolean get() = cities.first().latitude < 0
}

