    fun byCode(code: String): Country = countries.firstOrNull { it.code == code } ?: countries.first { it.code == "DE" }

    data class Nearest(val country: Country, val city: City, val distanceKm: Double)

    /** Closest table city to a coordinate (great-circle distance). */
    fun nearest(latitude: Double, longitude: Double): Nearest {
        var best: Nearest? = null
        for (c in countries) for (city in c.cities) {
            val d = haversineKm(latitude, longitude, city.latitude, city.longitude)
            if (best == null || d < best.distanceKm) best = Nearest(c, city, d)
        }
        return best!!
    }

    fun haversineKm(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
        val r = 6371.0088
        val p1 = Math.toRadians(lat1)
        val p2 = Math.toRadians(lat2)
        val dp = p2 - p1
        val dl = Math.toRadians(lon2 - lon1)
        val a = sin(dp / 2).pow(2) + cos(p1) * cos(p2) * sin(dl / 2).pow(2)
        return 2 * r * asin(sqrt(a))
    }
}
